<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/functions.php';require_once __DIR__.'/../config/session.php';Session::start();if(!Session::isLoggedIn()||Session::getUserRole()!=='supervisor'){header('Location: '.APP_URL.'index.php');exit();}$pageTitle=t('dashboard.supervisor_title');$active='dashboard';$uid=Session::getUserId();$myLetters=dbFetchAll("SELECT l.code,l.name_ar FROM supervisor_letters sl JOIN letters l ON l.id=sl.letter_id WHERE sl.supervisor_id=? ORDER BY l.sort_order",[$uid]);
$scopeSql="EXISTS (SELECT 1 FROM supervisor_letters sl WHERE sl.supervisor_id=? AND sl.letter_id=s.first_letter_id AND (CONVERT(sl.gender USING utf8mb4) COLLATE utf8mb4_unicode_ci=CONVERT(s.gender USING utf8mb4) COLLATE utf8mb4_unicode_ci OR CONVERT(sl.gender USING utf8mb4) COLLATE utf8mb4_unicode_ci IN ('both','all','كلاهما','الكل')))";
$s=dbFetchOne("SELECT (SELECT COUNT(*) FROM sponsors s WHERE $scopeSql) my_sponsors,(SELECT COUNT(*) FROM sponsorships sp JOIN sponsors s ON s.id=sp.sponsor_id WHERE sp.status='active' AND $scopeSql) my_active_sponsorships,(SELECT COUNT(DISTINCT sp.child_id) FROM sponsorships sp JOIN sponsors s ON s.id=sp.sponsor_id WHERE sp.status='active' AND $scopeSql) my_orphans,(SELECT COALESCE(SUM(sp.amount),0) FROM sponsor_payments sp JOIN sponsors s ON s.id=sp.sponsor_id WHERE sp.status='approved' AND DATE_FORMAT(sp.created_at,'%Y-%m')=DATE_FORMAT(CURDATE(),'%Y-%m') AND $scopeSql) month_collected",[$uid,$uid,$uid,$uid]);
/* Fina statistics use the existing sponsor_payments table; no legacy Fina table is required. */
$finaStats=dbFetchOne("SELECT COUNT(*) fina_total,SUM(status='pending') fina_pending,SUM(status='approved' AND DATE_FORMAT(created_at,'%Y-%m')=DATE_FORMAT(CURDATE(),'%Y-%m')) fina_approved_month FROM sponsor_payments WHERE supervisor_id=? AND notes LIKE 'FINA_ONLY|%'",[$uid]);
$recentPayments=dbFetchAll("SELECT sp.id,sp.created_at,sp.amount,sp.payment_method,sp.status,sp.payment_period,s.full_name sponsor_name FROM sponsor_payments sp JOIN sponsors s ON s.id=sp.sponsor_id WHERE sp.supervisor_id=? AND $scopeSql ORDER BY sp.created_at DESC,sp.id DESC LIMIT 20",[$uid,$uid]);$methodLabels=['cash'=>'نقدي','bank_transfer'=>'تحويل بنكي','credit_card'=>'بطاقة','mobile'=>'محفظة إلكترونية','other'=>'أخرى'];$statusLabels=['pending'=>'بانتظار المراجعة','approved'=>'معتمدة','returned'=>'مرتجعة','cancelled'=>'ملغاة'];include __DIR__.'/../includes/header.php';?>
